/// Writes every type of [`roots`] and the types they hold into `dir`, one file
/// each, and an `index.ts` that exports them. Two Rust types that would give
/// the same TypeScript name fail here instead of one hiding the other. Returns
/// the Rust name (`std::any::type_name`) of every type written.
fn generate(dir: &Path) -> Vec<&'static str> {
    struct Collect<'a> {
        config: &'a Config,
        /// TypeScript name to the Rust type that has it.
        seen: BTreeMap<String, (TypeId, &'static str)>,
    }

    impl TypeVisitor for Collect<'_> {
        fn visit<T: TS + 'static + ?Sized>(&mut self) {
            // A primitive or a wrapper such as `Vec` has no file.
            if T::output_path().is_none() {
                return;
            }
            let name = T::ident(self.config);
            let rust = std::any::type_name::<T>();
            if let Some((id, first)) = self.seen.get(&name) {
                assert!(
                    *id == TypeId::of::<T>(),
                    "`{first}` and `{rust}` are both `{name}` in TypeScript: rename one with #[ts(rename = \"...\")]"
                );
                return;
            }
            self.seen.insert(name, (TypeId::of::<T>(), rust));
            T::export(self.config).expect("a type is written");
            T::visit_dependencies(self);
        }
    }

    fs::create_dir_all(dir).expect("the directory is made");
    // Integers are `number`: the screens read them as such, and none of the
    // API's reaches 2^53.
    let config = Config::new().with_large_int("number").with_out_dir(dir);
    let mut collect = Collect {
        config: &config,
        seen: BTreeMap::new(),
    };
    roots(&mut collect);

    let mut index = String::from(NOTE);
    for name in collect.seen.keys() {
        index.push_str(&format!("export type {{ {name} }} from \"./{name}\";\n"));
    }
    fs::write(dir.join("index.ts"), index).expect("the index is written");
    collect.seen.values().map(|(_, rust)| *rust).collect()
}

/// Every file of `dir` by name.
fn read_dir(dir: &Path) -> BTreeMap<String, String> {
    let Ok(entries) = fs::read_dir(dir) else {
        return BTreeMap::new();
    };
    entries
        .map(|entry| {
            let path = entry.expect("an entry is read").path();
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            (name, fs::read_to_string(&path).expect("a file is read"))
        })
        .collect()
}

/// What differs between the generated files and the committed ones, one line
/// each; empty when they are the same.
fn differences(
    generated: &BTreeMap<String, String>,
    committed: &BTreeMap<String, String>,
) -> Vec<String> {
    let mut lines = Vec::new();
    for (name, text) in generated {
        match committed.get(name) {
            None => lines.push(format!("missing: {name}")),
            Some(old) if old != text => lines.push(format!("changed: {name}")),
            Some(_) => {}
        }
    }
    for name in committed.keys() {
        if !generated.contains_key(name) {
            lines.push(format!("stale: {name}"));
        }
    }
    lines
}

#[test]
fn committed_files_are_current() {
    let temp = tempfile::tempdir().expect("a temporary directory");
    generate(temp.path());
    let committed = committed_dir();
    let lines = differences(&read_dir(temp.path()), &read_dir(&committed));
    assert!(
        lines.is_empty(),
        "the generated TypeScript types in {COMMITTED} are not the ones the Rust types give; run `cargo types` from the repository root and commit the result:\n{}",
        lines.join("\n")
    );
}

/// Writes the committed files again; `cargo types` runs only this.
#[test]
#[ignore = "writes web/src/lib/api-types; run it with `cargo types`"]
fn write_committed_files() {
    let committed = committed_dir();
    if committed.exists() {
        fs::remove_dir_all(&committed).expect("the old files are removed");
    }
    generate(&committed);
}

#[test]
fn command_requests_are_the_ones_the_web_reads() {
    use serde_json::json;
    use trss_collect::commands::{
        anissia_captions::{self, AnissiaCaptions},
        episode_undo::{self, EpisodeUndo},
        receive_once::{self, ReceiveOnce},
        receive_past,
        rule_archive::{self, Direction, RuleArchive},
    };
    use trss_library::watch_rescan::{self, WatchRescan};

    use super::commands_api::{CommandKind, CommandPayload, CommandRequest, PastRequest, Request};
    use crate::archive_batch::{self, ArchiveBatch, BatchRule};

    // The kind each request the server reads is listed under. It has no
    // wildcard, so a `Request` added without its `CommandKind` does not
    // compile.
    fn listed(request: &Request) -> CommandKind {
        match request {
            Request::ReceiveOnce(_) => CommandKind::ReceiveOnce,
            Request::ReceivePast(_) => CommandKind::ReceivePast,
            Request::RuleArchive(_) => CommandKind::RuleArchive,
            Request::WatchRescan(_) => CommandKind::WatchRescan,
            Request::EpisodeUndo(_) => CommandKind::EpisodeUndo,
            Request::AnissiaCaptions(_) => CommandKind::AnissiaCaptions,
            Request::RuleArchiveBatch(_) => CommandKind::RuleArchiveBatch,
        }
    }

    let sent = [
        (
            receive_once::KIND,
            CommandKind::ReceiveOnce,
            CommandPayload::ReceiveOnce(ReceiveOnce::new(7)),
        ),
        (
            receive_past::KIND,
            CommandKind::ReceivePast,
            CommandPayload::ReceivePast(PastRequest {
                rule_id: "r".into(),
                search_id: "s".into(),
                key: "k".into(),
            }),
        ),
        (
            rule_archive::KIND,
            CommandKind::RuleArchive,
            CommandPayload::RuleArchive(RuleArchive {
                rule_id: "r".into(),
                direction: Direction::Archive,
                receive: Vec::new(),
            }),
        ),
        (
            watch_rescan::KIND,
            CommandKind::WatchRescan,
            CommandPayload::WatchRescan(WatchRescan {
                folder_id: "f".into(),
            }),
        ),
        (
            episode_undo::KIND,
            CommandKind::EpisodeUndo,
            CommandPayload::EpisodeUndo(EpisodeUndo {
                rule_id: "r".into(),
                episode: 3,
            }),
        ),
        (
            anissia_captions::KIND,
            CommandKind::AnissiaCaptions,
            CommandPayload::AnissiaCaptions(AnissiaCaptions { anime_no: 5 }),
        ),
        (
            archive_batch::KIND,
            CommandKind::RuleArchiveBatch,
            CommandPayload::RuleArchiveBatch(ArchiveBatch {
                rules: vec![BatchRule {
                    rule_id: "r".into(),
                    name: "n".into(),
                }],
            }),
        ),
    ];
    for (kind, listed_kind, command) in sent {
        assert_eq!(serde_json::to_value(&listed_kind).unwrap(), json!(kind));
        let body = serde_json::to_value(CommandRequest {
            id: "command-1".into(),
            command,
        })
        .unwrap();
        assert_eq!(body["id"], "command-1");
        assert_eq!(body["kind"], kind);
        let request = Request::read(kind, body["payload"].clone())
            .unwrap_or_else(|_| panic!("the web does not read the `{kind}` payload"));
        assert_eq!(request.kind(), kind);
        assert_eq!(
            serde_json::to_value(listed(&request)).unwrap(),
            serde_json::to_value(listed_kind).unwrap()
        );
    }
}

/// The enums that took the place of a `code()` string in a response send the
/// same text, so the JSON did not change.
#[test]
fn enums_serialize_as_their_codes() {
    use serde_json::json;
    use trss_collect::{
        commands::rule_archive::Direction,
        past_search::judge::State,
        plan::PastCause,
        store::{
            channels::{RuleState, SubtitleMode, UndoFileState},
            history::HistoryResult,
        },
    };
    use trss_core::commands::CommandState;
    use trss_library::store::setup::Step;

    use super::{
        archive_api::GroundKind,
        artwork_api::ImageStatus,
        library_work_api::StorageKind,
        past_search_api::PollState,
        rules_api::HeldBy,
        seasons_anissia_api::{EpisodeForm, TitleKind},
        seasons_api::Pending as SeasonPending,
        todo_api::{FailureRole, FailureState},
    };
    use crate::archive_batch::FailureKind;
    use trss_jobs::place::records;
    use trss_library::artwork::Unavailable;

    fn same<T: serde::Serialize + Copy>(all: &[T], code: impl Fn(T) -> &'static str) {
        for one in all {
            assert_eq!(serde_json::to_value(one).unwrap(), json!(code(*one)));
        }
    }

    same(&HistoryResult::ALL, HistoryResult::code);
    same(&Step::ALL, Step::code);
    same(
        &[
            State::Missing,
            State::Replace,
            State::VersionUnknown,
            State::Have,
            State::Superseded,
            State::Alternate,
            State::Batch,
            State::Unnumbered,
        ],
        State::code,
    );
    same(
        &[RuleState::Active, RuleState::Paused, RuleState::Archived],
        RuleState::as_str,
    );
    same(
        &[
            SubtitleMode::Follow,
            SubtitleMode::Undecided,
            SubtitleMode::None,
        ],
        SubtitleMode::as_str,
    );
    same(
        &[
            Direction::Archive,
            Direction::Restore,
            Direction::Start,
            Direction::Resume,
        ],
        Direction::code,
    );
    same(
        &[
            CommandState::Pending,
            CommandState::Running,
            CommandState::Done,
            CommandState::Failed,
        ],
        CommandState::code,
    );
    same(
        &[
            PastCause::Subscribed,
            PastCause::Titled,
            PastCause::Resumed,
            PastCause::FirstRead,
        ],
        PastCause::code,
    );
    same(
        &[
            UndoFileState::Pending,
            UndoFileState::Renamed,
            UndoFileState::Kept,
        ],
        UndoFileState::code,
    );

    // The library screens' codes.
    {
        use trss_core::settings::policy::SubtitleFormat;
        use trss_import::suggest::Kind as SuggestionKind;
        use trss_jobs::{
            model::{AssetKind, ItemState, SubtitleFormat as StoredFormat, Wait},
            place::cleanup::CleanKind,
            todo::Badge,
        };
        use trss_library::{
            discovery::Reason,
            mapping::{preview::Choice as MappingChoice, MappingKind},
            store::{
                artwork as cover,
                library::{Filter, Sort, SubtitleCoverage},
                seasons::{Note as SeasonNote, Origin},
            },
        };

        same(
            &[
                SubtitleCoverage::All,
                SubtitleCoverage::Some,
                SubtitleCoverage::None,
            ],
            SubtitleCoverage::code,
        );
        same(&Sort::ALL, Sort::code);
        same(&Filter::ALL, Filter::code);
        same(&Badge::ALL, Badge::code);
        same(&SubtitleFormat::ALL, SubtitleFormat::code);
        same(
            &[
                StoredFormat::Ass,
                StoredFormat::Srt,
                StoredFormat::Smi,
                StoredFormat::Other,
            ],
            StoredFormat::code,
        );
        same(
            &[
                AssetKind::Subtitle,
                AssetKind::Font,
                AssetKind::Attachment,
                AssetKind::Companion,
                AssetKind::Other,
            ],
            AssetKind::code,
        );
        same(
            &[
                CleanKind::Past,
                CleanKind::AwaitingVideo,
                CleanKind::Unplaced,
                CleanKind::Stored,
            ],
            CleanKind::code,
        );
        same(
            &[
                ItemState::Pending,
                ItemState::Running,
                ItemState::Waiting,
                ItemState::Held,
                ItemState::Failed,
                ItemState::Done,
            ],
            ItemState::code,
        );
        same(
            &[
                Wait::Auth,
                Wait::Subtitle,
                Wait::Placement,
                Wait::Approval,
                Wait::Video,
            ],
            Wait::code,
        );
        same(
            &[
                Reason::SeasonMismatch,
                Reason::OutsideSeason,
                Reason::InSubfolder,
                Reason::Partial,
                Reason::NoEpisode,
                Reason::InvalidName,
            ],
            Reason::code,
        );
        same(
            &[
                cover::Mode::Auto,
                cover::Mode::Manual,
                cover::Mode::Disabled,
            ],
            cover::Mode::code,
        );
        same(
            &[cover::Source::Anilist, cover::Source::Upload],
            cover::Source::code,
        );
        same(
            &[cover::Format::Jpeg, cover::Format::Png, cover::Format::Webp],
            cover::Format::code,
        );
        same(
            &[cover::JobKind::Search, cover::JobKind::Fetch],
            cover::JobKind::code,
        );
        same(
            &[
                cover::Note::NoMatch,
                cover::Note::Ambiguous,
                cover::Note::Incomplete,
                cover::Note::Failed,
                cover::Note::Gone,
                cover::Note::NoImage,
                cover::Note::Rejected,
            ],
            cover::Note::code,
        );
        same(&[Origin::Auto, Origin::User], Origin::code);
        same(
            &[
                SeasonNote::NoMatch,
                SeasonNote::Ambiguous,
                SeasonNote::Incomplete,
                SeasonNote::Failed,
            ],
            SeasonNote::code,
        );
        same(
            &[MappingKind::Auto, MappingKind::Undecided, MappingKind::User],
            MappingKind::code,
        );
        same(
            &[
                MappingChoice::Same,
                MappingChoice::Continue,
                MappingChoice::Custom,
            ],
            MappingChoice::code,
        );
        same(
            &[
                SuggestionKind::WithCreator,
                SuggestionKind::AddressOnly,
                SuggestionKind::Unreadable,
                SuggestionKind::None,
            ],
            SuggestionKind::code,
        );
        // The artwork status is `available` or an `Unavailable`'s code.
        for (one, text) in [
            (ImageStatus::Available, "available"),
            (
                ImageStatus::from(Unavailable::Missing),
                Unavailable::Missing.code(),
            ),
            (
                ImageStatus::from(Unavailable::Mismatch),
                Unavailable::Mismatch.code(),
            ),
            (
                ImageStatus::from(Unavailable::Unverified),
                Unavailable::Unverified.code(),
            ),
        ] {
            assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
        }
        // What the copy's choice said before.
        for (one, text) in [
            (records::Choice::Apply, "apply"),
            (records::Choice::Compare, "compare"),
        ] {
            assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
        }
    }

    // These took the place of string literals, not of a `code()`.
    for (one, text) in [
        (EpisodeForm::Number, "number"),
        (EpisodeForm::Zero, "zero"),
        (EpisodeForm::Text, "text"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (TitleKind::Native, "native"),
        (TitleKind::English, "english"),
        (TitleKind::Romaji, "romaji"),
        (TitleKind::Korean, "korean"),
        (TitleKind::Folder, "folder"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (StorageKind::Subtitle, "subtitle"),
        (StorageKind::Font, "font"),
        (StorageKind::Attachment, "attachment"),
        (StorageKind::Cover, "cover"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    assert_eq!(
        serde_json::to_value(SeasonPending::Search).unwrap(),
        json!("search")
    );
    for (one, text) in [(FailureRole::Old, "old"), (FailureRole::New, "new")] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (FailureState::Kept, "kept"),
        (FailureState::Removed, "removed"),
        (FailureState::ReceivedName, "received_name"),
        (FailureState::Missing, "missing"),
        (FailureState::NotReceived, "not_received"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (FailureKind::Refused, "refused"),
        (FailureKind::ArchiveFailed, "archive_failed"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (GroundKind::Ended, "ended"),
        (GroundKind::Unlisted, "unlisted"),
        (GroundKind::Quiet, "quiet"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (HeldBy::Subscription, "subscription"),
        (HeldBy::Link, "link"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (PollState::Running, "running"),
        (PollState::Failed, "failed"),
        (PollState::Done, "done"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
}

/// Every type a route of the API sends or takes as JSON is generated for the
/// screens (`docs/requirements/web-app.md`, 공통 라이브러리의 모듈 구성).
///
/// The check reads the sources of `web/`: each `Json<…>` of a handler names
/// the types of its request or response. Each name is resolved to a full path
/// (the module of the file that defines it, or what the file's `use` lines say)
/// and must be the path of a type [`roots`] reaches, so a generated type of the
/// same name elsewhere does not stand in for it. A name that cannot be
/// resolved fails the test instead of being guessed.
#[test]
fn every_json_type_of_a_route_is_generated() {
    /// Parses the tree of a `use` (`a::{b, c::d as e}`) into `(name, path)`
    /// pairs; a glob gives the name `*`.
    fn parse_use(
        c: &[char],
        i: &mut usize,
        prefix: &[String],
        out: &mut Vec<(String, Vec<String>)>,
    ) {
        let skip = |i: &mut usize| {
            while *i < c.len() && c[*i].is_whitespace() {
                *i += 1;
            }
        };
        let ident = |i: &mut usize| {
            let start = *i;
            while *i < c.len() && (c[*i].is_alphanumeric() || c[*i] == '_' || c[*i] == '*') {
                *i += 1;
            }
            c[start..*i].iter().collect::<String>()
        };
        loop {
            skip(i);
            if *i >= c.len() || c[*i] == '}' {
                return;
            }
            let mut path = prefix.to_vec();
            let mut grouped = false;
            loop {
                skip(i);
                if c[*i] == '{' {
                    *i += 1;
                    parse_use(c, i, &path, out);
                    skip(i);
                    *i += 1; // the closing brace
                    grouped = true;
                    break;
                }
                path.push(ident(i));
                skip(i);
                if c[*i..].starts_with(&[':', ':']) {
                    *i += 2;
                } else {
                    break;
                }
            }
            if !grouped {
                skip(i);
                let mut name = path.last().cloned().unwrap_or_default();
                if c[*i..].starts_with(&['a', 's', ' ']) {
                    *i += 3;
                    skip(i);
                    name = ident(i);
                }
                if path.last().is_some_and(|l| l == "self") {
                    path.pop();
                    if name == "self" {
                        name = path.last().cloned().unwrap_or_default();
                    }
                }
                out.push((name, path));
            }
            skip(i);
            if *i < c.len() && c[*i] == ',' {
                *i += 1;
            }
        }
    }

    /// The `use` declarations of `code` as `(name, absolute path)` pairs,
    /// relative paths resolved from `module`.
    fn uses(code: &str, module: &[String]) -> Vec<(String, Vec<String>)> {
        let mut found = Vec::new();
        for line_start in code.match_indices('\n').map(|(at, _)| at + 1).chain([0]) {
            let rest = &code[line_start..];
            let rest = rest
                .strip_prefix("pub(super) ")
                .or_else(|| rest.strip_prefix("pub(crate) "))
                .or_else(|| rest.strip_prefix("pub "))
                .unwrap_or(rest);
            let Some(rest) = rest.strip_prefix("use ") else {
                continue;
            };
            let end = rest.find(';').expect("a use ends");
            let chars: Vec<char> = rest[..end].chars().collect();
            let mut parsed = Vec::new();
            parse_use(&chars, &mut 0, &[], &mut parsed);
            for (name, path) in parsed {
                let mut absolute: Vec<String> = Vec::new();
                let mut segments = path.into_iter().peekable();
                match segments.peek().map(String::as_str) {
                    Some("crate") => {
                        segments.next();
                        absolute.push("trss".into());
                    }
                    Some("self") => {
                        segments.next();
                        absolute.extend(module.iter().cloned());
                    }
                    Some("super") => {
                        absolute.extend(module.iter().cloned());
                        while segments.peek().is_some_and(|s| s == "super") {
                            segments.next();
                            absolute.pop();
                        }
                    }
                    _ => {}
                }
                absolute.extend(segments);
                found.push((name, absolute));
            }
        }
        found
    }

    /// Whether `resolved` names `generated`: the same crate and name, and the
    /// modules between in the same order (a re-export skips some).
    fn names(resolved: &[String], generated: &[&str]) -> bool {
        if resolved.first().map(String::as_str) != generated.first().copied()
            || resolved.last().map(String::as_str) != generated.last().copied()
        {
            return false;
        }
        let mut rest = generated.iter();
        resolved.iter().all(|r| rest.any(|g| g == r))
    }

    let temp = tempfile::tempdir().expect("a temporary directory");
    // The definition path of every type generation reaches, without generics.
    let generated: Vec<Vec<&str>> = generate(temp.path())
        .into_iter()
        .map(|full| full.split('<').next().unwrap().split("::").collect())
        .collect();

    // Not types of ours.
    const STD: &[&str] = &[
        "Json",
        "JsonRejection",
        "Result",
        "Option",
        "Vec",
        "Box",
        "HashMap",
        "BTreeMap",
        "String",
        "Value",
        "ApiError",
        "StatusCode",
        "bool",
        "usize",
        "u32",
        "u64",
        "i32",
        "i64",
        "f64",
    ];

    // Read as text on purpose: the screens write `CommandRequest`, which is
    // generated, and `command_requests_are_the_ones_the_web_reads` keeps the
    // two together.
    const EXEMPT: &[&str] = &["trss::web::commands_api::CreateBody"];

    let web = Path::new(env!("CARGO_MANIFEST_DIR")).join("src/web");
    let mut files = Vec::new();
    let mut stack = vec![web.clone()];
    while let Some(dir) = stack.pop() {
        for entry in fs::read_dir(&dir).expect("a directory is read") {
            let path = entry.expect("an entry is read").path();
            if path.is_dir() {
                // The tests' sources and fixtures are not routes.
                if !matches!(
                    path.file_name().and_then(|n| n.to_str()),
                    Some("testing") | Some("tests")
                ) {
                    stack.push(path);
                }
            } else if path.extension().is_some_and(|e| e == "rs")
                && path
                    .file_name()
                    .is_some_and(|n| n != "tests.rs" && n != "api_types.rs")
            {
                files.push(path);
            }
        }
    }
    files.sort();

    // Every route module is merged into the router.
    let router = fs::read_to_string(web.join("api.rs")).expect("api.rs is read");
    for file in &files {
        let name = file.file_stem().unwrap().to_string_lossy();
        if file.parent() == Some(web.as_path()) && name.ends_with("_api") {
            assert!(
                router.contains(&format!("super::{name}::routes()")),
                "`{name}` has routes the router does not merge"
            );
        }
    }

    let mut missing = Vec::new();
    let mut unresolved = Vec::new();
    let mut checked = 0;
    for file in &files {
        let text = fs::read_to_string(file).expect("a source is read");
        // The part before the file's own tests module.
        let code = text.split("#[cfg(test)]\nmod tests {").next().unwrap();
        let relative = file.strip_prefix(&web).unwrap().with_extension("");
        let mut module: Vec<String> = vec!["trss".into(), "web".into()];
        module.extend(
            relative
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .filter(|c| c != "mod"),
        );
        let imported = uses(code, &module);
        let defines = |name: &str| {
            ["struct ", "enum "].iter().any(|kind| {
                code.match_indices(&format!("{kind}{name}")).any(|(at, m)| {
                    let before = code[..at].chars().next_back();
                    let after = code[at + m.len()..].chars().next();
                    !before.is_some_and(|c| c.is_alphanumeric() || c == '_')
                        && !after.is_some_and(|c| c.is_alphanumeric() || c == '_')
                })
            })
        };
        let at_file = file.strip_prefix(&web).unwrap().display().to_string();
        let mut rest = code;
        while let Some(at) = rest.find("Json<") {
            let inner_start = at + "Json<".len();
            let mut depth = 1;
            let mut end = inner_start;
            for (i, c) in rest[inner_start..].char_indices() {
                match c {
                    '<' => depth += 1,
                    '>' => depth -= 1,
                    _ => {}
                }
                if depth == 0 {
                    end = inner_start + i;
                    break;
                }
            }
            let inner = &rest[inner_start..end];
            for word in inner
                .split(|c: char| !(c.is_alphanumeric() || c == '_' || c == ':'))
                .filter(|w| !w.is_empty())
            {
                let parts: Vec<&str> = word.split("::").collect();
                let name = *parts.last().unwrap();
                // A generic parameter (`Json<T>`) is a single capital letter.
                if STD.contains(&name) || name.starts_with(char::is_lowercase) || name.len() == 1 {
                    continue;
                }
                checked += 1;
                // The path the file means by the word.
                let resolved: Option<Vec<String>> = if parts.len() == 1 && defines(name) {
                    let mut path = module.clone();
                    path.push(name.to_owned());
                    Some(path)
                } else {
                    imported
                        .iter()
                        .find(|(n, _)| n == parts[0])
                        .map(|(_, path)| {
                            let mut path = path.clone();
                            path.extend(parts[1..].iter().map(|p| (*p).to_owned()));
                            path
                        })
                };
                match resolved {
                    None => unresolved.push(format!("{at_file}: Json<{inner}> names `{word}`")),
                    Some(path) => {
                        if !EXEMPT.contains(&path.join("::").as_str())
                            && !generated.iter().any(|g| names(&path, g))
                        {
                            missing
                                .push(format!("{at_file}: Json<{inner}> is `{}`", path.join("::")));
                        }
                    }
                }
            }
            rest = &rest[end..];
        }
    }
    assert!(checked > 50, "only {checked} types were looked at");
    assert!(
        unresolved.is_empty(),
        "the check cannot tell which type these name; import them with a `use` or define them in the file:\n{}",
        unresolved.join("\n")
    );
    assert!(
        missing.is_empty(),
        "a route sends or takes JSON that the screens' generated types do not hold; derive `TS` on it and name it in `roots`:\n{}",
        missing.join("\n")
    );
}

/// The enums of the jobs, the upload, the replacement and the remote screen
/// took the place of strings and of `code()` texts, so the JSON did not change.
#[test]
fn job_and_screen_enums_serialize_as_the_strings_they_replaced() {
    use serde_json::json;
    use trss_jobs::{
        place::{episode::Assignment, unchanged::FontReceipt},
        store::FileShown,
    };
    use trss_subtitles::{
        compare::{Change as DialogueChange, Encoding, Format as ComparedFormat},
        upload::{Archive, Kind as UploadKind},
        verify::Format as FileFormat,
        FailureKind as ReceiptFailure,
    };

    use super::{
        events_api::{NoData, StreamEvent},
        jobs_api::{
            placement::Scope,
            replacement::{Answered, FormatLabel, Limit, Settled, Warning},
            Finishing, Restart, StepShown, UnpackShown,
        },
        screen_api::{DialogKind, EndedReason, ScreenShown},
    };

    fn same<T: serde::Serialize + Copy>(all: &[T], code: impl Fn(T) -> &'static str) {
        for one in all {
            assert_eq!(serde_json::to_value(one).unwrap(), json!(code(*one)));
        }
    }
    fn texts<T: serde::Serialize + Copy>(all: &[(T, &str)]) {
        for (one, text) in all {
            assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
        }
    }

    // The codes the records and the API already had.
    same(&FileFormat::ALL, FileFormat::code);
    same(&Archive::ALL, Archive::code);
    same(
        &[UploadKind::Subtitle, UploadKind::Font, UploadKind::Archive],
        UploadKind::code,
    );
    same(
        &[
            ReceiptFailure::Missing,
            ReceiptFailure::Expired,
            ReceiptFailure::NotAFile,
            ReceiptFailure::Changed,
            ReceiptFailure::Network,
            ReceiptFailure::NoSubtitle,
            ReceiptFailure::NeedsInput,
        ],
        ReceiptFailure::code,
    );
    // The comparison's format is named as the comparison names it.
    for format in [
        ComparedFormat::Ass,
        ComparedFormat::Srt,
        ComparedFormat::Vtt,
        ComparedFormat::Smi,
    ] {
        assert_eq!(
            serde_json::to_value(FormatLabel::from(format)).unwrap(),
            json!(format.label())
        );
    }

    // Strings the handlers wrote as literals.
    texts(&[
        (StepShown::Upcoming, "upcoming"),
        (StepShown::Current, "current"),
        (StepShown::Waiting, "waiting"),
        (StepShown::Done, "done"),
        (StepShown::Failed, "failed"),
        (StepShown::Partial, "partial"),
    ]);
    texts(&[
        (UnpackShown::Done, "done"),
        (UnpackShown::Failed, "failed"),
        (UnpackShown::Retry, "retry"),
        (UnpackShown::Volume, "volume"),
    ]);
    texts(&[
        (Finishing::Done, "done"),
        (Finishing::Finishing, "finishing"),
    ]);
    texts(&[(Restart::Running, "running")]);
    texts(&[
        (FileShown::Receiving, "receiving"),
        (FileShown::Held, "held"),
        (FileShown::Done, "done"),
        (FileShown::Failed, "failed"),
    ]);
    texts(&[
        (Assignment::Mapped, "mapped"),
        (Assignment::SameNumber, "same_number"),
        (Assignment::Explicit, "explicit"),
    ]);
    texts(&[
        (FontReceipt::Unchanged, "unchanged"),
        (FontReceipt::Same, "same"),
        (FontReceipt::New, "new"),
    ]);
    texts(&[
        (Scope::Whole, "whole"),
        (Scope::Relocate, "relocate"),
        (Scope::Held, "held"),
    ]);
    texts(&[
        (Warning::OverwriteUnmanaged, "overwrite_unmanaged"),
        (Warning::RemoveApplied, "remove_applied"),
    ]);
    texts(&[
        (Limit::UnknownSource, "unknown_source"),
        (Limit::LinesUnknown, "lines_unknown"),
    ]);
    texts(&[(Settled::Approved, "approved"), (Settled::Kept, "kept")]);
    texts(&[
        (Answered::Approved, "approved"),
        (Answered::Kept, "kept"),
        (Answered::Stale, "stale"),
    ]);
    texts(&[
        (DialogueChange::Added, "added"),
        (DialogueChange::Changed, "changed"),
        (DialogueChange::Removed, "removed"),
    ]);
    texts(&[
        (Encoding::Utf8, "UTF-8"),
        (Encoding::Utf16, "UTF-16"),
        (Encoding::Cp949, "CP949"),
    ]);
    texts(&[
        (ScreenShown::Ready, "ready"),
        (ScreenShown::Preparing, "preparing"),
        (ScreenShown::Closed, "closed"),
        (ScreenShown::Unavailable, "unavailable"),
    ]);
    texts(&[
        (EndedReason::Browser, "browser"),
        (EndedReason::Run, "run"),
        (EndedReason::Unreachable, "unreachable"),
        (EndedReason::Stuck, "stuck"),
        (EndedReason::Replaced, "replaced"),
    ]);
    texts(&[
        (DialogKind::Alert, "alert"),
        (DialogKind::Confirm, "confirm"),
        (DialogKind::Prompt, "prompt"),
        (DialogKind::Beforeunload, "beforeunload"),
    ]);

    // The names and data the stream sends its events under.
    for (event, name, data) in [
        (StreamEvent::Ready(NoData {}), "ready", "{}"),
        (
            StreamEvent::Change(trss_core::changes::Change {
                kind: trss_core::changes::ChangeKind::Command,
                id: Some("c1".into()),
            }),
            "change",
            r#"{"kind":"command","id":"c1"}"#,
        ),
        (StreamEvent::Lagged(NoData {}), "lagged", "{}"),
        (StreamEvent::Alive(NoData {}), "alive", "{}"),
    ] {
        assert_eq!(event.wire(), (name.to_owned(), data.to_owned()));
    }
}

/// `ErrorBody` replaced `json!` bodies: `current` is absent when there is none
/// and `null` only when the server's value is `null`, as the `json!` built them
/// (`"current"` was left out unless a handler had a value).
#[test]
fn error_body_keeps_current_absent_or_null_as_before() {
    use serde_json::{json, Value};

    use super::error::{AlreadySubscribed, ErrorBody, ErrorCode};

    let none = serde_json::to_value(ErrorBody::new(ErrorCode::Invalid, "m")).unwrap();
    assert_eq!(none, json!({"error": "invalid", "message": "m"}));
    assert!(none.get("current").is_none());

    let mut null = ErrorBody::new(ErrorCode::Conflict, "m");
    null.current = Some(Value::Null);
    let null = serde_json::to_value(null).unwrap();
    assert_eq!(
        null,
        json!({"error": "conflict", "message": "m", "current": null})
    );
    assert!(null.get("current").is_some());

    let rule = serde_json::to_value(AlreadySubscribed {
        rule_id: "r1".into(),
    })
    .unwrap();
    assert_eq!(rule, json!({"rule_id": "r1"}));

    for (code, text) in [
        (ErrorCode::NotFound, "not_found"),
        (ErrorCode::Unavailable, "unavailable"),
        (ErrorCode::Internal, "internal"),
        (ErrorCode::HostNotAllowed, "host_not_allowed"),
        (ErrorCode::Forbidden, "forbidden"),
        (ErrorCode::Gone, "gone"),
    ] {
        assert_eq!(serde_json::to_value(code).unwrap(), json!(text));
    }
}
